from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expression must have exactly 5 fields")

    # Field ranges: (min, max)
    field_ranges = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day of month
        (1, 12),   # month
        (0, 7),    # day of week (0 and 7 are Sunday)
    ]

    parsed_fields = []
    is_unrestricted = []

    for i, field_str in enumerate(fields):
        min_val, max_val = field_ranges[i]
        items = field_str.split(',')
        values = set()
        for item in items:
            if item == '':
                raise ValueError(f"Empty item in field {i}")
            if '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError(f"Invalid step syntax in field {i}: {item}")
                base_str, step_str = parts
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError(f"Non-digit step in field {i}: {step_str}")
                if step < 1:
                    raise ValueError(f"Step must be >= 1 in field {i}: {step}")
                if base_str == '*':
                    start = min_val
                    end = max_val
                elif '-' in base_str:
                    range_parts = base_str.split('-')
                    if len(range_parts) != 2:
                        raise ValueError(f"Invalid range in field {i}: {base_str}")
                    try:
                        a = int(range_parts[0])
                        b = int(range_parts[1])
                    except ValueError:
                        raise ValueError(f"Non-digit in range in field {i}: {base_str}")
                    if a > b:
                        raise ValueError(f"A > B in range in field {i}: {base_str}")
                    if a < min_val or a > max_val or b < min_val or b > max_val:
                        raise ValueError(f"Out of range in field {i}: {base_str}")
                    start = a
                    end = b
                else:
                    try:
                        n = int(base_str)
                    except ValueError:
                        raise ValueError(f"Non-digit in field {i}: {base_str}")
                    if n < min_val or n > max_val:
                        raise ValueError(f"Out of range in field {i}: {base_str}")
                    start = n
                    end = max_val
                for v in range(start, end + 1, step):
                    values.add(v)
            elif '-' in item:
                range_parts = item.split('-')
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid range in field {i}: {item}")
                try:
                    a = int(range_parts[0])
                    b = int(range_parts[1])
                except ValueError:
                    raise ValueError(f"Non-digit in range in field {i}: {item}")
                if a > b:
                    raise ValueError(f"A > B in range in field {i}: {item}")
                if a < min_val or a > max_val or b < min_val or b > max_val:
                    raise ValueError(f"Out of range in field {i}: {item}")
                for v in range(a, b + 1):
                    values.add(v)
            elif item == '*':
                for v in range(min_val, max_val + 1):
                    values.add(v)
            else:
                try:
                    n = int(item)
                except ValueError:
                    raise ValueError(f"Non-digit in field {i}: {item}")
                if n < min_val or n > max_val:
                    raise ValueError(f"Out of range in field {i}: {item}")
                values.add(n)
        parsed_fields.append(sorted(values))
        is_unrestricted.append(field_str == '*')

    # Normalize day-of-week: 7 -> 0 (both mean Sunday)
    dow_values = parsed_fields[4]
    dow_values_normalized = set()
    for v in dow_values:
        if v == 7:
            dow_values_normalized.add(0)
        else:
            dow_values_normalized.add(v)
    parsed_fields[4] = sorted(dow_values_normalized)

    # Determine if day-of-month and day-of-week are restricted
    dom_restricted = not is_unrestricted[2]
    dow_restricted = not is_unrestricted[4]

    # Start from after, but set seconds and microseconds to 0, then add 1 minute to be strictly after
    candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    max_days = 3000
    for _ in range(max_days * 24 * 60):  # worst case, iterate minute by minute
        if candidate.month in parsed_fields[3]:  # month
            if candidate.hour in parsed_fields[1]:  # hour
                if candidate.minute in parsed_fields[0]:  # minute
                    # Check day matching
                    dom_match = candidate.day in parsed_fields[2]
                    # Day of week: Python's weekday: Monday=0, Sunday=6. Cron: Sunday=0, Monday=1, ..., Saturday=6
                    # So cron_dow = (python_weekday + 1) % 7
                    python_weekday = candidate.weekday()  # Monday=0, Sunday=6
                    cron_dow = (python_weekday + 1) % 7
                    dow_match = cron_dow in parsed_fields[4]

                    if dom_restricted and dow_restricted:
                        if dom_match or dow_match:
                            return candidate
                    else:
                        if dom_match and dow_match:
                            return candidate
        candidate += timedelta(minutes=1)

    raise ValueError("No match found within 3000 days")

