from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expression must have exactly 5 fields")

    # Field definitions: (min_val, max_val)
    field_ranges = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day of month
        (1, 12),   # month
        (0, 7),    # day of week (0 and 7 are Sunday)
    ]

    parsed_fields = []
    is_unrestricted = []

    for i, field_str in enumerate(fields):
        min_val, max_val = field_ranges[i]
        items = field_str.split(',')
        values = set()
        for item in items:
            if item == '':
                raise ValueError(f"Empty item in field {i}")
            if '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError(f"Invalid step syntax in field {i}: {item}")
                base_str, step_str = parts
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError(f"Non-digit step in field {i}: {item}")
                if step < 1:
                    raise ValueError(f"Step must be >= 1 in field {i}: {item}")
                if base_str == '*':
                    start = min_val
                    end = max_val
                elif '-' in base_str:
                    range_parts = base_str.split('-')
                    if len(range_parts) != 2:
                        raise ValueError(f"Invalid range in field {i}: {item}")
                    try:
                        a = int(range_parts[0])
                        b = int(range_parts[1])
                    except ValueError:
                        raise ValueError(f"Non-digit in range in field {i}: {item}")
                    if a > b:
                        raise ValueError(f"A > B in range in field {i}: {item}")
                    start = a
                    end = b
                else:
                    try:
                        start = int(base_str)
                    except ValueError:
                        raise ValueError(f"Non-digit in field {i}: {item}")
                    end = max_val
                for v in range(start, end + 1, step):
                    if v < min_val or v > max_val:
                        raise ValueError(f"Value {v} out of range in field {i}")
                    values.add(v)
            elif '-' in item:
                range_parts = item.split('-')
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid range in field {i}: {item}")
                try:
                    a = int(range_parts[0])
                    b = int(range_parts[1])
                except ValueError:
                    raise ValueError(f"Non-digit in range in field {i}: {item}")
                if a > b:
                    raise ValueError(f"A > B in range in field {i}: {item}")
                for v in range(a, b + 1):
                    if v < min_val or v > max_val:
                        raise ValueError(f"Value {v} out of range in field {i}")
                    values.add(v)
            elif item == '*':
                for v in range(min_val, max_val + 1):
                    values.add(v)
            else:
                try:
                    v = int(item)
                except ValueError:
                    raise ValueError(f"Non-digit in field {i}: {item}")
                if v < min_val or v > max_val:
                    raise ValueError(f"Value {v} out of range in field {i}")
                values.add(v)
        parsed_fields.append(sorted(values))
        is_unrestricted.append(field_str == '*')

    # Normalize day-of-week: 7 -> 0 (Sunday)
    dow_values = parsed_fields[4]
    dow_values_normalized = set()
    for v in dow_values:
        if v == 7:
            dow_values_normalized.add(0)
        else:
            dow_values_normalized.add(v)
    parsed_fields[4] = sorted(dow_values_normalized)

    # Determine if day fields are restricted
    dom_restricted = not is_unrestricted[2]
    dow_restricted = not is_unrestricted[4]

    # Start searching from the next minute after `after`
    # We want strictly after `after`, so start at after + 1 second, then round up to next minute
    start = after + timedelta(seconds=1)
    # Round up to the next minute (set seconds and microseconds to 0, but we need strictly after)
    # Actually, let's just iterate minute by minute
    # To be efficient, we can start from the next minute boundary
    candidate = start.replace(second=0, microsecond=0)
    if candidate <= after:
        candidate += timedelta(minutes=1)

    max_days = 3000
    max_dt = after + timedelta(days=max_days)

    # Precompute month lengths for efficiency
    def is_leap_year(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def days_in_month(year, month):
        if month in [1, 3, 5, 7, 8, 10, 12]:
            return 31
        elif month in [4, 6, 9, 11]:
            return 30
        elif month == 2:
            return 29 if is_leap_year(year) else 28
        return 0

    # Convert day-of-week to match Python's weekday(): Monday=0, Sunday=6
    # Cron: 0=Sunday, 1=Monday, ..., 6=Saturday, 7=Sunday
    # Python: Monday=0, Tuesday=1, ..., Sunday=6
    def cron_dow_to_python_dow(cron_dow):
        # cron_dow: 0=Sun, 1=Mon, ..., 6=Sat, 7=Sun
        # python_dow: 0=Mon, 1=Tue, ..., 6=Sun
        if cron_dow == 0:
            return 6  # Sunday
        elif cron_dow == 7:
            return 6  # Sunday
        else:
            return cron_dow - 1  # Mon=1->0, Tue=2->1, ..., Sat=6->5

    python_dow_set = set()
    for cd in parsed_fields[4]:
        python_dow_set.add(cron_dow_to_python_dow(cd))

    minute_vals = parsed_fields[0]
    hour_vals = parsed_fields[1]
    dom_vals = parsed_fields[2]
    month_vals = parsed_fields[3]
    # dow_vals are already normalized to 0-6 for Sunday

    current = candidate
    while current <= max_dt:
        year = current.year
        month = current.month
        day = current.day
        hour = current.hour
        minute = current.minute

        # Check month
        if month not in month_vals:
            # Skip to next valid month
            # Find next valid month
            found = False
            for m in month_vals:
                if m > month:
                    # Go to first day of next valid month
                    current = datetime(year, m, 1, 0, 0)
                    found = True
                    break
            if not found:
                # Go to next year, first valid month
                next_year = year + 1
                if next_year > max_dt.year:
                    raise ValueError("No match within 3000 days")
                current = datetime(next_year, month_vals[0], 1, 0, 0)
            continue

        # Check day
        # Determine if day matches
        day_matches = False
        if dom_restricted and dow_restricted:
            # Either must match
            dom_match = day in dom_vals
            # Check day of week
            python_dow = current.weekday()
            dow_match = python_dow in python_dow_set
            day_matches = dom_match or dow_match
        else:
            # Both must match
            dom_match = day in dom_vals
            python_dow = current.weekday()
            dow_match = python_dow in python_dow_set
            day_matches = dom_match and dow_match

        if not day_matches:
            # Skip to next day
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check hour
        if hour not in hour_vals:
            # Find next valid hour
            found = False
            for h in hour_vals:
                if h > hour:
                    current = current.replace(hour=h, minute=minute_vals[0])
                    found = True
                    break
            if not found:
                # Go to next day
                current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check minute
        if minute not in minute_vals:
            # Find next valid minute
            found = False
            for m in minute_vals:
                if m > minute:
                    current = current.replace(minute=m)
                    found = True
                    break
            if not found:
                # Go to next hour
                # Find next valid hour
                found_h = False
                for h in hour_vals:
                    if h > hour:
                        current = current.replace(hour=h, minute=minute_vals[0])
                        found_h = True
                        break
                if not found_h:
                    # Go to next day
                    current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # All fields match
        return current.replace(second=0, microsecond=0)

    raise ValueError("No match within 3000 days")

