def glob_match(pattern, path):
    r"""Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    # Parse the pattern into segments, respecting '/' as delimiter and handling escapes and char classes
    segments = []
    current_segment = []
    i = 0
    n = len(pattern)

    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("Trailing lone backslash")
            current_segment.append(('literal', pattern[i + 1]))
            i += 2
        elif c == '[':
            # Parse char class
            i += 1
            if i >= n:
                raise ValueError("Unterminated [")
            negate = False
            if i < n and pattern[i] == '!':
                negate = True
                i += 1
            chars = set()
            first = True
            while i < n and pattern[i] != ']':
                if i + 2 < n and pattern[i + 1] == '-' and pattern[i + 2] != ']':
                    start_char = pattern[i]
                    end_char = pattern[i + 2]
                    for code in range(ord(start_char), ord(end_char) + 1):
                        chars.add(chr(code))
                    i += 3
                else:
                    chars.add(pattern[i])
                    i += 1
                first = False
            if i >= n:
                raise ValueError("Unterminated [")
            i += 1 # skip ]
            current_segment.append(('char_class', chars, negate))
        elif c == '?':
            current_segment.append(('any_char',))
            i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                current_segment.append(('double_star',))
                i += 2
            else:
                current_segment.append(('any_string',))
                i += 1
        elif c == '/':
            segments.append(current_segment)
            current_segment = []
            i += 1
        else:
            current_segment.append(('literal', c))
            i += 1
    segments.append(current_segment)

    # Convert segments into parsed_segments
    # A segment is a double_star if it has exactly one token which is 'double_star'
    parsed_segments = []
    for seg in segments:
        if len(seg) == 1 and seg[0][0] == 'double_star':
            parsed_segments.append(('double_star',))
        else:
            # Merge consecutive any_string tokens into one
            merged = []
            for tok in seg:
                if tok[0] == 'any_string' and merged and merged[-1][0] == 'any_string':
                    # Skip this one, as it's redundant
                    continue
                merged.append(tok)
            parsed_segments.append(('segment', merged))

    # Split path into segments
    path_segments = path.split('/') if path else []

    m = len(path_segments)
    p = len(parsed_segments)

    # dp[i][j] = True if path_segments[:i] matches parsed_segments[:j]
    dp = [[False] * (p + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, p + 1):
        if parsed_segments[j - 1][0] == 'double_star':
            # Double star can match zero or more path segments
            for i in range(m + 1):
                if i == 0:
                    dp[i][j] = dp[i][j-1]
                else:
                    dp[i][j] = dp[i][j-1] or dp[i-1][j]
        else:
            # Normal segment
            seg_tokens = parsed_segments[j - 1][1]
            for i in range(1, m + 1):
                if dp[i-1][j-1] and _match_segment(path_segments[i-1], seg_tokens):
                    dp[i][j] = True

    return dp[m][p]


def _match_segment(path_seg, tokens):
    """Match a single path segment against a list of tokens."""
    i = 0
    n = len(path_seg)
    t = 0
    nt = len(tokens)

    while t < nt:
        tok = tokens[t]
        if tok[0] == 'literal':
            if i >= n or path_seg[i] != tok[1]:
                return False
            i += 1
            t += 1
        elif tok[0] == 'any_char':
            if i >= n or path_seg[i] == '/':
                return False
            i += 1
            t += 1
        elif tok[0] == 'any_string':
            # * matches zero or more chars except /
            # Try to match the rest of the tokens with the rest of the path
            # Since we've merged consecutive *, there's at most one * here
            for k in range(i, n + 1):
                if _match_segment(path_seg[k:], tokens[t+1:]):
                    return True
            return False
        elif tok[0] == 'char_class':
            if i >= n or path_seg[i] == '/':
                return False
            chars, negate = tok[1], tok[2]
            if negate:
                if path_seg[i] in chars:
                    return False
            else:
                if path_seg[i] not in chars:
                    return False
            i += 1
            t += 1
        else:
            return False

    return i == n

